for name, content in icons.items():
    path = os.path.join(icons_dir, name)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    size = os.path.getsize(path)
    print(f'Written: {name} ({size} bytes)')

print(f'\nTotal icons: {len(icons)}')
